import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { basename, dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { articleTitleEntries as defaultArticleTitleEntries } from './title-metadata.mjs';
import { assertCanonicalArticleMarkdown } from './markdown-headings.mjs';

const MODULE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const TITLE_ASSET_PREFIX =
  '// Generated by scripts/generate-title-map.mjs. Do not edit manually.\n' +
  '(function (root) {\n' +
  "  'use strict';\n" +
  '  root.CODESOME_ARTICLE_TITLES = Object.freeze(';
const TITLE_ASSET_VERSION_MARKER = ');\n  root.CODESOME_ARTICLE_TITLES_VERSION = ';
const TITLE_ASSET_SUFFIX = ';\n}(window));\n';
const HOME_ARTICLE = '03-Agentic入门宝典.md';

export const REQUIRED_TITLE_PIPELINE_SCRIPTS = [
  'assets/page-title.js',
  'assets/vendor/docsify.min.js',
  'assets/article-titles.js',
  'assets/cdc-title-injector.js',
  'assets/vendor/search.min.js'
];

const runtimeCache = new Map();

function defaultReadSource(root, site) {
  return readFileSync(resolve(root, site), 'utf8');
}

function expectedTitleMap(entries) {
  return Object.fromEntries(entries.map(({ site, title }) => [site, title]));
}

function expectedTitleMapVersion(entries) {
  const canonicalMap = JSON.stringify(expectedTitleMap(entries));
  return `title-map-${createHash('sha256').update(canonicalMap).digest('hex').slice(0, 16)}`;
}

function assertEqualTitleMaps(actual, expected) {
  if (!actual || typeof actual !== 'object' || Array.isArray(actual)) {
    throw new Error('generated title asset does not contain an object map');
  }
  const actualKeys = Object.keys(actual).sort();
  const expectedKeys = Object.keys(expected).sort();
  if (JSON.stringify(actualKeys) !== JSON.stringify(expectedKeys)) {
    throw new Error('generated title asset entries differ from title metadata');
  }
  for (const key of expectedKeys) {
    if (typeof actual[key] !== 'string' || actual[key] !== expected[key]) {
      throw new Error(`generated title asset title differs from metadata: ${key}`);
    }
  }
}

export function parseGeneratedTitleAsset(source) {
  if (typeof source !== 'string' || !source.startsWith(TITLE_ASSET_PREFIX)) {
    throw new Error('generated title asset has an unexpected format');
  }
  const versionMarker = source.indexOf(TITLE_ASSET_VERSION_MARKER, TITLE_ASSET_PREFIX.length);
  if (versionMarker === -1) throw new Error('generated title asset has no version marker');

  const mapText = source.slice(TITLE_ASSET_PREFIX.length, versionMarker);
  const versionStart = versionMarker + TITLE_ASSET_VERSION_MARKER.length;
  if (!source.endsWith(TITLE_ASSET_SUFFIX)) throw new Error('generated title asset has an invalid suffix');
  const versionText = source.slice(versionStart, -TITLE_ASSET_SUFFIX.length);

  let map;
  let version;
  try {
    map = JSON.parse(mapText);
    version = JSON.parse(versionText);
  } catch (error) {
    throw new Error(`generated title asset is not valid JSON: ${error.message}`);
  }
  if (typeof version !== 'string' || !version) throw new Error('generated title asset version is invalid');
  return { map, version };
}

function readRuntimeFile(root, path, readFile) {
  try {
    const source = readFile
      ? readFile(path)
      : readFileSync(resolve(root, path), 'utf8');
    if (typeof source !== 'string') throw new Error('runtime reader returned non-text content');
    return source;
  } catch (error) {
    throw new Error(`${path}: cannot read runtime file (${error.message})`);
  }
}

function parseIndexScripts(index, root, readFile) {
  const sourcePattern = /<script\b[^>]*\bsrc="([^"]+)"/g;
  const baseUrl = new URL('http://codesome-runtime.local/');
  const scripts = [];
  for (const match of index.matchAll(sourcePattern)) {
    const source = match[1];
    let url;
    try {
      url = new URL(source, baseUrl);
    } catch {
      throw new Error(`index.html has an invalid script URL: ${source}`);
    }
    if (url.origin !== baseUrl.origin) continue;

    const path = decodeURIComponent(url.pathname).replace(/^\/+/, '');
    const absolutePath = resolve(root, path);
    const relativePath = relative(root, absolutePath);
    if (!path || relativePath.startsWith('..') || relativePath.includes('..')) {
      throw new Error(`index.html has an invalid local script path: ${source}`);
    }
    try {
      readRuntimeFile(root, path, readFile);
    } catch {
      throw new Error(`index.html references a missing browser resource: ${path}`);
    }
    scripts.push({ path, source, search: url.search });
  }
  return scripts;
}

function assertIndexTitlePipeline(index, root, expectedVersion, readFile) {
  const scripts = parseIndexScripts(index, root, readFile);
  const positions = new Map();
  for (const path of REQUIRED_TITLE_PIPELINE_SCRIPTS) {
    const matches = scripts.filter(script => script.path === path);
    if (matches.length !== 1) {
      throw new Error(`index.html must reference ${path} exactly once`);
    }
    positions.set(path, scripts.indexOf(matches[0]));
  }

  for (let index = 1; index < REQUIRED_TITLE_PIPELINE_SCRIPTS.length; index += 1) {
    const previous = positions.get(REQUIRED_TITLE_PIPELINE_SCRIPTS[index - 1]);
    const current = positions.get(REQUIRED_TITLE_PIPELINE_SCRIPTS[index]);
    if (previous >= current) throw new Error('index.html title pipeline script order is invalid');
  }

  const titleScript = scripts.find(script => script.path === 'assets/article-titles.js');
  if (titleScript.source !== `./assets/article-titles.js?v=${expectedVersion}`) {
    throw new Error('index.html title map script version is stale');
  }
  return scripts;
}

function assertSidebar(sidebar, entries) {
  const links = [...sidebar.matchAll(/^\s*-\s*\[([^\]]+)\]\(([^)]+)\)/gm)]
    .map(([, title, href]) => ({ title: title.trim(), href: href.trim() }));
  const articleLinks = links.filter(({ href }) => {
    const path = href.split(/[?#]/)[0];
    return path === '/' || /^\d{2}-.*\.md$/i.test(basename(path));
  });
  const errors = [];

  for (const { site, title } of entries) {
    const matching = articleLinks.filter(({ href }) => {
      const path = href.split(/[?#]/)[0];
      return site === HOME_ARTICLE ? path === '/' : basename(path) === site;
    });
    if (matching.length !== 1) {
      errors.push(`${site}: sidebar must contain exactly one article link (found ${matching.length})`);
    } else if (matching[0].title !== title) {
      errors.push(`${site}: sidebar title differs from registered title`);
    }
  }
  if (articleLinks.length !== entries.length) {
    errors.push(`sidebar article link count differs: expected ${entries.length}, found ${articleLinks.length}`);
  }
  if (errors.length) throw new Error(errors.join('\n'));
}

function assertTitlePipelineAssets(root, readFile) {
  const injector = readRuntimeFile(root, 'assets/cdc-title-injector.js', readFile);
  const requiredInjectorMarkers = [
    'CODESOME_TITLE_PIPELINE',
    'hook.beforeEach',
    'Docsify.get',
    'failPipeline',
    'registered article source is not canonical'
  ];
  for (const marker of requiredInjectorMarkers) {
    if (!injector.includes(marker)) {
      throw new Error(`title injector is missing required behavior: ${marker}`);
    }
  }

  const pageTitle = readRuntimeFile(root, 'assets/page-title.js', readFile);
  if (!pageTitle.includes('reportFallback')) throw new Error('page-title layer has no fail-closed fallback check');
  if (/<h1\b/i.test(pageTitle) || /createElement\s*\(\s*['"]h1['"]\s*\)/i.test(pageTitle)) {
    throw new Error('page-title layer must not synthesize an H1');
  }
  if (pageTitle.includes('page-title-fallback')) throw new Error('page-title layer contains a legacy H1 fallback');
}

export function runtimeFingerprint(root, entries) {
  const paths = [
    'index.html',
    '_sidebar.md',
    ...REQUIRED_TITLE_PIPELINE_SCRIPTS,
    ...entries.map(({ site }) => site)
  ];
  return paths.map(path => {
    try {
      const source = readFileSync(resolve(root, path));
      return `${path}:${createHash('sha256').update(source).digest('hex')}`;
    } catch {
      return `${path}:missing`;
    }
  }).join('|');
}

export function assertPublicArticleSources(
  entries = defaultArticleTitleEntries,
  readSource = site => defaultReadSource(MODULE_ROOT, site)
) {
  const errors = [];
  for (const { site, title } of entries) {
    try {
      assertCanonicalArticleMarkdown(readSource(site), title);
    } catch (error) {
      errors.push(`${site}: ${error.message}`);
    }
  }
  if (errors.length) throw new Error(`public article title contract failed:\n${errors.join('\n')}`);
  return entries.length;
}

export function assertPublicRuntimeContract({
  root = MODULE_ROOT,
  entries = defaultArticleTitleEntries,
  readSource,
  readRuntimeFile: readRuntimeFileOption
} = {}) {
  const runtimeRoot = resolve(root);
  const sourceReader = readSource || (site => defaultReadSource(runtimeRoot, site));
  const titleMap = expectedTitleMap(entries);
  const expectedVersion = expectedTitleMapVersion(entries);
  const errors = [];

  try {
    assertPublicArticleSources(entries, sourceReader);
  } catch (error) {
    errors.push(error.message);
  }

  try {
    const generated = parseGeneratedTitleAsset(
      readRuntimeFile(runtimeRoot, 'assets/article-titles.js', readRuntimeFileOption)
    );
    assertEqualTitleMaps(generated.map, titleMap);
    if (generated.version !== expectedVersion) {
      throw new Error(`generated title asset version differs: expected ${expectedVersion}, found ${generated.version}`);
    }
  } catch (error) {
    errors.push(error.message);
  }

  let scripts;
  try {
    scripts = assertIndexTitlePipeline(
      readRuntimeFile(runtimeRoot, 'index.html', readRuntimeFileOption),
      runtimeRoot,
      expectedVersion,
      readRuntimeFileOption
    );
  } catch (error) {
    errors.push(error.message);
  }

  try {
    assertTitlePipelineAssets(runtimeRoot, readRuntimeFileOption);
  } catch (error) {
    errors.push(error.message);
  }

  try {
    assertSidebar(readRuntimeFile(runtimeRoot, '_sidebar.md', readRuntimeFileOption), entries);
  } catch (error) {
    errors.push(error.message);
  }

  if (errors.length) {
    throw new Error(`public runtime title contract failed:\n${errors.join('\n')}`);
  }
  return {
    articleCount: entries.length,
    titleMapVersion: expectedVersion,
    scriptPaths: scripts.map(script => script.path)
  };
}

export function publicRuntimeHealth({ root = MODULE_ROOT, entries = defaultArticleTitleEntries, readSource } = {}) {
  const runtimeRoot = resolve(root);
  const useCache = !readSource && entries === defaultArticleTitleEntries;
  const fingerprint = useCache ? runtimeFingerprint(runtimeRoot, entries) : null;
  const cached = useCache && runtimeCache.get(runtimeRoot);
  if (cached && cached.fingerprint === fingerprint) return cached.result;

  let result;
  try {
    result = { ok: true, ...assertPublicRuntimeContract({ root: runtimeRoot, entries, readSource }) };
  } catch (error) {
    result = { ok: false, articleCount: 0, titleMapVersion: null, error: error.message };
  }
  if (useCache) runtimeCache.set(runtimeRoot, { fingerprint, result });
  return result;
}
